-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.admin_account_labels(ids uuid[])
 RETURNS TABLE(id uuid, email text, name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform public.require_admin_session();
  if ids is null or cardinality(ids) > 500 then
    raise exception 'admin_account_labels: at most 500 accounts' using errcode = '22023';
  end if;
  return query
    select u.id, u.email::text,
           nullif(trim(coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name', '')), '')
      from auth.users u
     where u.id = any(ids)
     order by u.email;
end;
$function$;

grant execute on function public.admin_account_labels(ids uuid[]) to authenticated;
grant execute on function public.admin_account_labels(ids uuid[]) to service_role;
